//! Fixture skeleton and mesh: a box-shaped gun with box hands, identical for every weapon.
//!
//! Original geometry generated by code. It deliberately resembles nothing from MW2 beyond
//! "a box-shaped gun" (sheet 03 section 8).
//!
//! Axes follow MW2: x forward, y left, z up, inches. Every box is built with outward-facing,
//! counter-clockwise triangles; a unit test checks the winding against the stored normals.

use crate::model::{
    AlphaMode, BoneData, CullMode, ModelSlotData, PartRole, Skeleton, SurfaceData, VertexSkin,
    ViewmodelMesh,
};

/// Bone indices of the fixture skeleton.
pub mod bone {
    pub const TAG_ORIGIN: u16 = 0;
    pub const TAG_VIEW: u16 = 1;
    pub const J_GUN: u16 = 2;
    pub const TAG_FLASH: u16 = 3;
    pub const J_MAG: u16 = 4;
    pub const J_WRIST_RI: u16 = 5;
    pub const J_WRIST_LE: u16 = 6;
    pub const TAG_BRASS: u16 = 7;
}

/// Texture slots used by the fixture surfaces.
pub mod tex {
    /// Gun body: dark with light stripes and a one-texel red mark in the top-right corner.
    pub const GUN: u16 = 0;
    /// Hands: flat skin tone with a darker knuckle band.
    pub const HANDS: u16 = 1;
    /// Magazine: olive.
    pub const MAG: u16 = 2;
    /// Alpha-tested plate with square holes.
    pub const FLAP: u16 = 3;
    /// Number of textures per weapon.
    pub const COUNT: u32 = 4;
}

/// (name, parent, local bind translation) of each bone, in index order.
/// Bind rotations are identity, so a bone's world position is the sum of its ancestors' offsets.
const BONES: [(&str, Option<u16>, [f32; 3]); 8] = [
    ("tag_origin", None, [0.0, 0.0, 0.0]),
    ("tag_view", Some(bone::TAG_ORIGIN), [0.0, 0.0, 0.0]),
    ("j_gun", Some(bone::TAG_VIEW), [14.0, -5.0, -6.0]),
    ("tag_flash", Some(bone::J_GUN), [18.0, 0.0, 1.0]),
    ("j_mag", Some(bone::J_GUN), [2.0, 0.0, -2.5]),
    ("j_wrist_ri", Some(bone::TAG_VIEW), [10.0, -5.0, -9.0]),
    ("j_wrist_le", Some(bone::TAG_VIEW), [22.0, -3.0, -8.0]),
    ("tag_brass", Some(bone::J_GUN), [6.0, -1.0, 1.0]),
];

/// Local bind translation of the bone named `name`, if it exists.
pub fn bind_translation(name: &str) -> Option<[f32; 3]> {
    BONES.iter().find(|b| b.0 == name).map(|b| b.2)
}

/// Index of the bone named `name`, if it exists.
pub fn bone_index(name: &str) -> Option<u16> {
    BONES
        .iter()
        .position(|b| b.0 == name)
        .and_then(|i| u16::try_from(i).ok())
}

fn world_position(index: usize) -> [f32; 3] {
    let mut p = [0.0f32; 3];
    let mut at = Some(index);
    while let Some(i) = at {
        let (_, parent, t) = BONES[i];
        for k in 0..3 {
            p[k] += t[k];
        }
        at = parent.map(usize::from);
    }
    p
}

/// Builds the skeleton.
pub fn skeleton() -> Skeleton {
    let bones = BONES
        .iter()
        .enumerate()
        .map(|(i, &(name, parent, t))| {
            let w = world_position(i);
            BoneData {
                name: name.to_owned(),
                model: 0,
                parent,
                bind_rotation: [0.0, 0.0, 0.0, 1.0],
                bind_translation: t,
                bind_world: glam::Mat4::from_translation(glam::Vec3::from(w)).to_cols_array(),
                no_scale: false,
            }
        })
        .collect();
    Skeleton {
        bones,
        models: vec![ModelSlotData {
            name: "fixture_viewmodel".to_owned(),
            base: 0,
            bone_count: BONES.len() as u16,
            scale: 1.0,
        }],
        duplicates: Vec::new(),
        view_bone: bone::TAG_VIEW,
        camera_bone: None,
        flash_bone: Some(bone::TAG_FLASH),
        brass_bone: Some(bone::TAG_BRASS),
        collapsed_bones: Vec::new(),
    }
}

/// Face table: (normal axis, normal sign, u axis, v axis) with `u x v = n`, so walking the
/// corners (0,0), (1,0), (1,1), (0,1) is counter-clockwise seen from outside.
const FACES: [(usize, f32, usize, usize); 6] = [
    (0, 1.0, 1, 2),
    (0, -1.0, 2, 1),
    (1, 1.0, 2, 0),
    (1, -1.0, 0, 2),
    (2, 1.0, 0, 1),
    (2, -1.0, 1, 0),
];

fn single_bone(bone: u16) -> VertexSkin {
    VertexSkin {
        bones: [bone, 0, 0, 0],
        weights: [1.0, 0.0, 0.0, 0.0],
    }
}

/// What a surface looks like; everything else about a box comes from its geometry.
struct Look {
    name: &'static str,
    texture: Option<u16>,
    alpha: AlphaMode,
    cull: CullMode,
    role: PartRole,
}

#[derive(Default)]
struct Builder {
    mesh: Option<ViewmodelMesh>,
}

impl Builder {
    fn mesh(&mut self) -> &mut ViewmodelMesh {
        self.mesh.get_or_insert_with(|| ViewmodelMesh {
            positions: Vec::new(),
            normals: Vec::new(),
            uvs: Vec::new(),
            skin: Vec::new(),
            indices: Vec::new(),
            surfaces: Vec::new(),
        })
    }

    fn begin(&mut self) -> u32 {
        self.mesh().indices.len() as u32
    }

    fn end(&mut self, start: u32, look: Look) {
        let mesh = self.mesh();
        let count = mesh.indices.len() as u32 - start;
        mesh.surfaces.push(SurfaceData {
            name: look.name.to_owned(),
            index_start: start,
            index_count: count,
            texture: look.texture,
            alpha: look.alpha,
            cull: look.cull,
            role: look.role,
            model: 0,
        });
    }

    /// Adds an axis-aligned box centred at `center` with edge lengths `size`, each face split
    /// into `grid` x `grid` quads, rigidly skinned to `bone`.
    fn add_box(&mut self, center: [f32; 3], size: [f32; 3], grid: u32, bone: u16, look: Look) {
        let start = self.begin();
        let mesh = self.mesh();
        for &(n_axis, n_sign, u_axis, v_axis) in &FACES {
            let base = mesh.positions.len() as u32;
            let mut normal = [0.0f32; 3];
            normal[n_axis] = n_sign;
            for tj in 0..=grid {
                for si in 0..=grid {
                    let s = si as f32 / grid as f32;
                    let t = tj as f32 / grid as f32;
                    let mut p = center;
                    p[n_axis] += n_sign * size[n_axis] * 0.5;
                    p[u_axis] += (s - 0.5) * size[u_axis];
                    p[v_axis] += (t - 0.5) * size[v_axis];
                    mesh.positions.push(p);
                    mesh.normals.push(normal);
                    mesh.uvs.push([s, t]);
                    mesh.skin.push(single_bone(bone));
                }
            }
            let stride = grid + 1;
            for tj in 0..grid {
                for si in 0..grid {
                    let a = base + tj * stride + si;
                    let b = a + 1;
                    let c = a + stride + 1;
                    let d = a + stride;
                    mesh.indices.extend_from_slice(&[a, b, c, a, c, d]);
                }
            }
        }
        self.end(start, look);
    }

    /// A 3-row by 2-column strip facing +y whose rows blend from `top_bone` through an even
    /// mix to `bottom_bone`. Exercises vertex weights. Two-sided.
    fn add_blend_strip(
        &mut self,
        x: [f32; 2],
        y: f32,
        z: [f32; 3],
        top_bone: u16,
        bottom_bone: u16,
        look: Look,
    ) {
        let start = self.begin();
        let mesh = self.mesh();
        let base = mesh.positions.len() as u32;
        let mix = [1.0f32, 0.5, 0.0];
        for (r, &zr) in z.iter().enumerate() {
            for (c, &xc) in x.iter().enumerate() {
                mesh.positions.push([xc, y, zr]);
                mesh.normals.push([0.0, 1.0, 0.0]);
                mesh.uvs.push([c as f32, r as f32 / 2.0]);
                mesh.skin.push(VertexSkin {
                    bones: [top_bone, bottom_bone, 0, 0],
                    weights: [mix[r], 1.0 - mix[r], 0.0, 0.0],
                });
            }
        }
        for r in 0..2u32 {
            let a = base + r * 2; // (r, c0)
            let b = a + 1; // (r, c1)
            let c = a + 2; // (r+1, c0)
            let d = a + 3; // (r+1, c1)
            // z decreases with the row, so these two triangles face +y.
            mesh.indices.extend_from_slice(&[a, b, c, b, d, c]);
        }
        self.end(start, look);
    }
}

/// Builds the mesh. Surfaces, in order: gun body, barrel, magazine, right hand, left hand,
/// alpha-tested blend flap, rocket, knife, scope lens.
pub fn mesh() -> ViewmodelMesh {
    let gun = world_position(usize::from(bone::J_GUN));
    let mag = world_position(usize::from(bone::J_MAG));
    let wrist_ri = world_position(usize::from(bone::J_WRIST_RI));
    let wrist_le = world_position(usize::from(bone::J_WRIST_LE));
    let flash = world_position(usize::from(bone::TAG_FLASH));
    let off = |p: [f32; 3], d: [f32; 3]| [p[0] + d[0], p[1] + d[1], p[2] + d[2]];

    let opaque = |name, texture, role| Look {
        name,
        texture: Some(texture),
        alpha: AlphaMode::Opaque,
        cull: CullMode::Back,
        role,
    };

    let mut b = Builder::default();
    b.add_box(
        gun,
        [16.0, 3.0, 4.0],
        3,
        bone::J_GUN,
        opaque("fixture_gun_body", tex::GUN, PartRole::Gun),
    );
    b.add_box(
        off(gun, [13.0, 0.0, 1.0]),
        [10.0, 1.2, 1.2],
        1,
        bone::J_GUN,
        opaque("fixture_gun_barrel", tex::GUN, PartRole::Gun),
    );
    b.add_box(
        off(mag, [0.0, 0.0, -1.5]),
        [2.0, 2.0, 5.0],
        2,
        bone::J_MAG,
        opaque("fixture_magazine", tex::MAG, PartRole::Gun),
    );
    b.add_box(
        wrist_ri,
        [4.0, 3.0, 3.0],
        1,
        bone::J_WRIST_RI,
        opaque("fixture_hand_right", tex::HANDS, PartRole::Hands),
    );
    b.add_box(
        wrist_le,
        [4.0, 3.0, 3.0],
        1,
        bone::J_WRIST_LE,
        opaque("fixture_hand_left", tex::HANDS, PartRole::Hands),
    );
    b.add_blend_strip(
        [gun[0] + 1.0, gun[0] + 3.0],
        gun[1] + 2.0,
        [gun[2] - 2.0, mag[2], mag[2] - 1.5],
        bone::J_GUN,
        bone::J_MAG,
        Look {
            name: "fixture_flap",
            texture: Some(tex::FLAP),
            alpha: AlphaMode::Test { cutoff: 0.5 },
            cull: CullMode::None,
            role: PartRole::Attachment,
        },
    );
    // Parts whose visibility sheets 10/11 decide: a rocket in front of the muzzle, a knife
    // under the barrel, a scope lens above the receiver.
    b.add_box(
        off(flash, [3.0, 0.0, 0.0]),
        [4.0, 2.4, 2.4],
        1,
        bone::J_GUN,
        opaque("fixture_rocket", tex::MAG, PartRole::Rocket),
    );
    b.add_box(
        off(gun, [14.0, 0.0, -2.0]),
        [7.0, 0.4, 1.2],
        1,
        bone::J_GUN,
        opaque("fixture_knife", tex::GUN, PartRole::Knife),
    );
    b.add_box(
        off(gun, [4.0, 0.0, 3.5]),
        [0.2, 2.0, 2.0],
        1,
        bone::J_GUN,
        Look {
            name: "fixture_scope_lens",
            texture: None,
            alpha: AlphaMode::Blend,
            cull: CullMode::None,
            role: PartRole::ScopeLens,
        },
    );
    b.mesh().clone()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bone_world_positions_follow_the_hierarchy() {
        let s = skeleton();
        let flash = glam::Mat4::from_cols_array(&s.bones[usize::from(bone::TAG_FLASH)].bind_world);
        assert_eq!(flash.w_axis.truncate(), glam::Vec3::new(32.0, -5.0, -5.0));
        for (i, b) in s.bones.iter().enumerate() {
            assert_eq!(b.name, BONES[i].0);
            assert!(b.parent.is_none_or(|p| usize::from(p) < i));
        }
        assert_eq!(bone_index("j_mag"), Some(bone::J_MAG));
        assert_eq!(bind_translation("j_gun"), Some([14.0, -5.0, -6.0]));
        assert_eq!(bone_index("nope"), None);
    }

    /// Every back-face-culled triangle must wind counter-clockwise seen from outside, i.e. its
    /// geometric normal agrees with the stored vertex normal.
    #[test]
    fn winding_agrees_with_normals() {
        let m = mesh();
        let mut checked = 0;
        for surf in &m.surfaces {
            let range = surf.index_start as usize..(surf.index_start + surf.index_count) as usize;
            for tri in m.indices[range].as_chunks::<3>().0 {
                let p = |i: u32| glam::Vec3::from(m.positions[i as usize]);
                let n = (p(tri[1]) - p(tri[0])).cross(p(tri[2]) - p(tri[0]));
                assert!(n.length() > 1e-6, "degenerate triangle in {}", surf.name);
                let stored = glam::Vec3::from(m.normals[tri[0] as usize]);
                assert!(
                    n.normalize().dot(stored) > 0.99,
                    "{}: triangle {tri:?} winds against its normal",
                    surf.name
                );
                checked += 1;
            }
        }
        assert!(checked > 150, "{checked} triangles");
    }

    #[test]
    fn surface_summary() {
        let m = mesh();
        assert_eq!(m.surfaces.len(), 9);
        assert_eq!(m.indices.len() % 3, 0);
        assert!(m.surfaces.iter().any(|s| s.role == PartRole::Rocket));
        assert!(m.surfaces.iter().any(|s| s.role == PartRole::Knife));
        assert!(m.surfaces.iter().any(|s| s.role == PartRole::ScopeLens));
        assert!(
            m.surfaces
                .iter()
                .any(|s| matches!(s.alpha, AlphaMode::Test { .. }))
        );
        assert!(m.surfaces.iter().any(|s| s.texture.is_none()));
        // The blend flap really has two-bone vertices.
        assert!(
            m.skin
                .iter()
                .any(|v| v.weights[0] > 0.0 && v.weights[1] > 0.0)
        );
    }
}
